import{_ as a,o as e,a as l,b as i}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"IterateNBatch","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateNBatch"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateNBatch.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateNBatch.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787294517000}'),r={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateNBatch.md"};function d(h,t,c,n,o,s){return e(),l("div",null,[...t[0]||(t[0]=[i(`<div><article class="markdown-body"><h1>IterateNBatch</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>调用一次IterateNBatch，会进行N次IterateBatch计算，计算出N个多Batch的singleCoreM * singleCoreN大小的C矩阵。在调用该接口前，需将MatmulConfig中的<a href="MatmulConfig.html#matmulconfig-params">isNBatch</a>参数设为true，开启多Batch输入多Batch输出功能，并调用<a href="SetWorkspace.html">SetWorkspace</a>接口申请临时空间，用于缓存计算结果，即IterateNBatch的结果输出至<a href="SetWorkspace.html">SetWorkspace</a>指定的Global Memory内存中。</p><p>对于BSNGD、SBNGD、BNGS1S2的Layout格式，调用该接口之前需要在tiling中使用SetALayout/SetBLayout/SetCLayout/SetBatchNum设置A/B/C的Layout轴信息和最大BatchNum数；对于Normal数据格式则需使用<a href="../Matmul_Tiling/SetBatchInfoForNormal.html">SetBatchInfoForNormal</a>设置A/B/C的M/N/K轴信息和A/B矩阵的BatchNum数。实例化Matmul时，通过MatmulType设置Layout类型，当前支持3种Layout类型：BSNGD、SBNGD、BNGS1S2。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;bool sync = true, bool waitIterateBatch = false&gt;
__aicore__ inline void IterateNBatch(const uint32_t batchLoop, uint32_t batchA, uint32_t batchB, bool enSequentialWrite, const uint32_t matrixStrideA = 0, const uint32_t matrixStrideB = 0, const uint32_t matrixStrideC = 0)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sync</td><td>获取C矩阵过程分为同步和异步两种模式：<br>同步：需要同步等待IterateNBatch执行结束，后续由开发者自行获取输出到Global Memory上的计算结果。<br>异步：不需要同步等待IterateNBatch执行结束。<br><br>通过该参数设置同步或者异步模式：同步模式设置为true；异步模式设置为false。默认为同步模式。</td></tr><tr><td>waitIterateBatch</td><td>是否需要通过<a href="WaitIterateBatch.html">WaitIterateBatch</a>接口等待IterateNBatch执行结束，仅在异步场景下使用。默认为false。<br><br>true：需要通过WaitIterateBatch接口等待IterateNBatch执行结束，然后由开发者自行获取输出到Global Memory上的计算结果。<br><br>false：不需要通过WaitIterateBatch接口等待IterateNBatch执行结束。调用本接口后，需要调用<a href="GetBatchTensorC.html">GetBatchTensorC</a>接口获取C矩阵，或者由开发者自行处理等待IterateNBatch执行结束的过程。</td></tr></tbody></table><p><strong>表2</strong> 接口参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>batchLoop</td><td>输入</td><td>当前计算的BMM个数。</td></tr><tr><td>batchA</td><td>输入</td><td>当前单次BMM调用计算左矩阵的batch数。</td></tr><tr><td>batchB</td><td>输入</td><td>当前单次BMM调用计算右矩阵的batch数，brc场景batchA/B不相同。</td></tr><tr><td>enSequentialWrite</td><td>输入</td><td>输出是否连续存放数据。</td></tr><tr><td>matrixStrideA</td><td>输入</td><td>A矩阵源操作数相邻nd矩阵起始地址间的偏移，默认值是0。</td></tr><tr><td>matrixStrideB</td><td>输入</td><td>B矩阵源操作数相邻nd矩阵起始地址间的偏移，默认值是0。</td></tr><tr><td>matrixStrideC</td><td>输入</td><td>该参数预留，保持默认值0即可。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>单BMM内计算遵循之前的约束条件。</li><li>对于BSNGD、SBNGD、BNGS1S2 Layout格式，输入A、B矩阵多Batch数据总和应小于L1 Buffer的大小。</li><li>当开启MixDualMaster（双主模式）场景时，即模板参数<a href="MatmulConfig.html#matmulconfig-params">enableMixDualMaster</a>设置为true，不支持使用该接口。</li><li>当使用ND格式输入，且单个BMM内A或B矩阵的<a href="IterateBatch.html#row_width">源矩阵内轴</a>大于65535时，需在MatmulConfig中设置intrinsicsCheck为true。开启此选项后，API会将一次从Global Memory到L1 Buffer的ND2NZ搬运操作拆分为多次循环搬运，从而避免单次搬运指令参数超限。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>实例功能：完成aGM、bGM矩阵乘，结果保存到cGm上，其中aGM数据的layout格式为BSNGD，bGM数据的layout格式为BSNGD，cGM的layout格式为BNGS1S2，左矩阵每次计算batchA个SD数据，右矩阵每次计算batchB个SD数据。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 创建Matmul实例
AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm1;
AscendC::TPipe pipe;
g_cubeTPipePtr = &amp;pipe;

REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm1);
mm1.Init(&amp;tiling);
int g_lay = tiling.ALayoutInfoG &gt; tiling.BLayoutInfoG ? tiling.ALayoutInfoG : tiling.BLayoutInfoG;
int for_extent = tiling.ALayoutInfoB * tiling.ALayoutInfoN * g_lay / tiling.BatchNum;
mm1.SetTensorA(gm_a[0], isTransposeAIn);
mm1.SetTensorB(gm_b[0], isTransposeBIn);
mm1.SetWorkspace(workspaceGM, 0);
if (tiling.isBias) {
    mm1.SetBias(gm_bias[0]);
}
// 多batch Matmul计算
mm1.IterateNBatch(for_extent, batchA, batchB, false);
</code></pre></div></article></div>`,1)])])}const m=a(r,[["render",d]]);export{p as __pageData,m as default};
